import {
  QuickOrderItemsList,
  QuickOrderNotificationBanner,
  QuickOrderDisabledOverlay,
} from '@/b2b-quick-order/components';
import { useQuickOrderItems } from '@/b2b-quick-order/hooks';
import { QuickOrderItemsProps } from '@/b2b-quick-order/types';
import { config } from '@/b2b-quick-order/api/initialize';
import { useText } from '@adobe-commerce/elsie/i18n';
import { classes, Container } from '@adobe-commerce/elsie/lib';
import { useRef, useEffect } from 'preact/hooks';

export const QuickOrderItems: Container<QuickOrderItemsProps> = ({
  className,
  slots,
  getProductsData,
  handleAddToCart,
  productsSearch,
  searchFilter,
}) => {
  const isQuickOrderActive = config.getConfig().quickOrderActive;
  const notificationRef = useRef<HTMLDivElement>(null);

  const t = useText({
    title: 'QuickOrder.QuickOrderItem.title',
    quantity: 'QuickOrder.QuickOrderItem.quantity',
    price: 'QuickOrder.QuickOrderItem.price',
    remove: 'QuickOrder.QuickOrderItem.remove',
    removeItem: 'QuickOrder.QuickOrderItem.removeItem',
    showOptions: 'QuickOrder.QuickOrderItem.showOptions',
    hideOptions: 'QuickOrder.QuickOrderItem.hideOptions',
    additionalOptions: 'QuickOrder.QuickOrderItem.additionalOptions',
    noAdditionalOptions: 'QuickOrder.QuickOrderItem.noAdditionalOptions',
    emptyList: 'QuickOrder.QuickOrderItem.emptyList',
    sku: 'QuickOrder.QuickOrderItem.sku',
    loading: 'QuickOrder.QuickOrderItem.loading',
    productNotFound: 'QuickOrder.QuickOrderItem.productNotFound',
    productNotFoundDescription:
      'QuickOrder.QuickOrderItem.productNotFoundDescription',
    productOptions: 'QuickOrder.QuickOrderItem.productOptions',
    configurableProductError:
      'QuickOrder.QuickOrderItem.configurableProductError',
    configurableProductErrorDescription:
      'QuickOrder.QuickOrderItem.configurableProductErrorDescription',
    addAllToCart: 'QuickOrder.QuickOrderItem.addAllToCart',
    configurableOptionsWarning:
      'QuickOrder.QuickOrderItem.configurableOptionsWarning',
    configurableOptionsWarningDescription:
      'QuickOrder.QuickOrderItem.configurableOptionsWarningDescription',
    outOfStock: 'QuickOrder.QuickOrderItem.outOfStock',
    searchPlaceholder: 'QuickOrder.Search.placeholder',
    searchAriaLabel: 'QuickOrder.Search.ariaLabel',
    searchEmptyState: 'QuickOrder.Search.emptyState',
    resultsAvailable: 'QuickOrder.Search.resultsAvailable',
    resultAvailable: 'QuickOrder.Search.resultAvailable',
    srInstructions: 'QuickOrder.Search.srInstructions',
    notificationValidationError:
      'QuickOrder.QuickOrderItem.notification.validationError',
    notificationBackendError:
      'QuickOrder.QuickOrderItem.notification.backendError',
    notificationSuccess: 'QuickOrder.QuickOrderItem.notification.success',
    notificationPartialSuccess:
      'QuickOrder.QuickOrderItem.notification.partialSuccess',
    disabledMessage: 'QuickOrder.QuickOrderItem.disabledMessage',
  });

  const {
    items,
    loading,
    removeItem,
    clearItems,
    updateItemQuantity,
    addToCart,
    isItemUpdating,
    setDisabledCartButton,
    isDisabledButton,
    notification,
    dismissNotification,
  } = useQuickOrderItems({
    getProductsData,
    handleAddToCart,
  });

  // Auto-scroll to notification banner when error appears
  useEffect(() => {
    if (
      notification &&
      notification.variant === 'warning' &&
      notificationRef.current
    ) {
      notificationRef.current.scrollIntoView({
        behavior: 'smooth',
        block: 'start',
      });
    }
  }, [notification]);

  const handleSkuClick = (sku: string) => {
    // Find the form element with matching data-sku attribute
    const formElement = document.querySelector(
      `form[data-sku="${sku}"]`
    ) as HTMLElement;

    if (formElement) {
      // Scroll to the element with smooth behavior
      formElement.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    }
  };

  return (
    <div
      className={classes([
        'b2b-quick-order-quick-order-items',
        !isQuickOrderActive && 'b2b-quick-order-disabled',
        className,
      ])}
      data-testid="quick-order-items"
      style={{ position: 'relative' }}
    >
      <div ref={notificationRef}>
        <QuickOrderNotificationBanner
          notification={notification}
          onDismiss={dismissNotification}
          onSkuClick={handleSkuClick}
          validationErrorText={t.notificationValidationError}
          backendErrorText={t.notificationBackendError}
          successText={t.notificationSuccess}
          partialSuccessText={t.notificationPartialSuccess}
        />
      </div>
      <QuickOrderDisabledOverlay
        isDisabled={!isQuickOrderActive}
        message={t.disabledMessage}
      >
        <QuickOrderItemsList
          t={t}
          items={items}
          onRemove={removeItem}
          clearItems={clearItems}
          onUpdateQuantity={updateItemQuantity}
          handleAddToCart={addToCart}
          isItemUpdating={isItemUpdating}
          slots={slots}
          loading={loading}
          setDisabledCartButton={setDisabledCartButton}
          isDisabledButton={isDisabledButton}
          productsSearch={productsSearch}
          searchFilter={searchFilter}
        />
      </QuickOrderDisabledOverlay>
    </div>
  );
};
